/* FabricNavigator API configuration lives in its own administration tab. */
(function(){
 if(location.pathname!=='/admin/'||document.querySelector('.fn-api-admin-panel'))return;
 var nav=document.querySelector('.fn-admin-tabs'),grid=document.querySelector('main.page .grid');if(!nav||!grid)return;
 var de=(document.documentElement.lang||lang||'en').toLowerCase().indexOf('de')===0;
 var tab=document.createElement('button');tab.type='button';tab.id='fn-admin-tab-api';tab.className='fn-admin-tab';tab.dataset.tab='api';tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.tabIndex=-1;tab.textContent='API';
 var system=nav.querySelector('.fn-admin-system-tab');nav.insertBefore(tab,system||null);
 var panel=document.createElement('section');panel.className='fn-admin-tab-panel fn-admin-system-panel fn-api-admin-panel';panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML='<iframe class="fn-admin-system-frame" title="FabricNavigator API" src="/admin/api.jsp"></iframe>';grid.appendChild(panel);
 function fit(){var frame=panel.querySelector('iframe');if(!frame)return;try{var body=frame.contentDocument&&frame.contentDocument.body;if(body)frame.style.height=Math.max(520,body.scrollHeight+8)+'px';}catch(ignored){}}
 function show(){grid.querySelectorAll('.fn-admin-tab-panel').forEach(function(item){item.hidden=item!==panel;});nav.querySelectorAll('[role="tab"]').forEach(function(item){var active=item===tab;item.classList.toggle('active',active);item.setAttribute('aria-selected',active?'true':'false');item.tabIndex=active?0:-1;});try{localStorage.setItem('fnAdminTab','api');}catch(ignored){}fit();}
 tab.addEventListener('click',show);nav.addEventListener('click',function(event){var other=event.target.closest('[role="tab"]');if(other&&other!==tab)panel.hidden=true;},true);
 var frame=panel.querySelector('iframe');frame.addEventListener('load',function(){fit();try{frame.contentDocument.documentElement.lang=de?'de':'en';frame.contentDocument.documentElement.setAttribute('data-theme',document.documentElement.getAttribute('data-theme')||'light');}catch(ignored){}});
 try{if(localStorage.getItem('fnAdminTab')==='api')show();}catch(ignored){}
}());
